function field(formKey,d){const val=drafts[formKey]?.[d.name]??d.value;if(d.type==='multiselect'){const selected=Array.isArray(val)?val:String(val||'').split(',');return `<details class="ve-choice"><summary>${e(d.title)}</summary><input class="input" data-ve-option-search placeholder="${t('بحث داخل الخيارات','Search options')}" />${(d.options||[]).map(x=>`<label><input type="checkbox" name="${d.name}" data-ve-multi="${d.name}" value="${e(x.id)}" ${selected.includes(x.id)?'checked':''} />${e(x.name||x.englishName||l(x.id))}</label>`).join('')}</details>`;}return `<label>${e(d.title)}${d.required?' *':''}${d.options?`<select name="${d.name}" class="input" ${d.required?'required':''}><option value="">—</option>${d.options.map(x=>`<option value="${e(x.id)}" ${String(val)===String(x.id)?'selected':''}>${e(x.name||x.englishName||l(x.id))}</option>`).join('')}</select>`:d.type==='checkbox'?`<input type="checkbox" name="${d.name}" ${val===true||val==='on'?'checked':''} />`:d.type==='textarea'?`<textarea class="input" name="${d.name}" rows="4" ${d.required?'required':''} maxlength="10000">${e(val)}</textarea>`:`<input class="input" name="${d.name}" type="${d.type}" value="${d.type==='file'?'':e(val)}" ${d.required?'required':''} ${d.type==='file'?(formKey==='import'?'accept=".csv,.xlsx"':'accept=".pdf,.png,.jpg,.jpeg,.webp"'):'maxlength="4000"'} />`}</label>`;}
