function reset(){fileHistory=false;epoch++;actor=null;cap=null;rows=[];requests=[];profile=null;request=null;clientContext=null;mode='list';tab='personal';busy=false;notice='';files=[];circulars=[];review=null;preview=null;report=null;importJob=null;linkedTasks=null;taskError='';drafts={};}
function sync(){const who=ABCentral?.actor?.id;if(who!==actor){reset();actor=who;}}
async function api(path,method='GET',body){const n=epoch,who=ABCentral?.actor?.id;const r=await ABCentral.api(path,method,body,method==='GET'?undefined:ids());if(n!==epoch||who!==ABCentral?.actor?.id)throw Error('staleSession');return r;}
function draw(){if(app.state.currentPage==='vehicles')render();}
function show(msg){notice=msg;const n=document.getElementById('ve-notice');if(n)n.textContent=msg;}
async function load(){if(busy)return;busy=true;try{cap=await api('vehicles/capabilities');if(cap.available){const saved=await api('vehicle-preferences');if(Array.isArray(saved.columns)&&saved.columns.length)prefs=saved;const old=prefs.filters||{},g=JSON.parse(old.grid||'{}');g.values={...g.values};if(old.companies)g.values.companyId=old.companies.split(',');if(old.statuses)g.values.status=old.statuses.split(',');prefs.filters={q:old.q||'',grid:JSON.stringify(g)};await list(true);const r=await api('vehicle-requests');requests=r.rows;references={investors:r.investors,employees:r.employees};circulars=(await api('vehicle-circulars')).rows;}}catch(err){if(err.message!=='staleSession')notice=error(err.message);}finally{busy=false;draw();}}
async function list(replace){const {grid,...query}=prefs.filters;const r=await api('registers/vehicles?'+new URLSearchParams({query:JSON.stringify(query),grid:grid||'{}',offset:String(replace?0:rows.length),limit:'50'}));registerMeta.facets=r.facets;total=r.total;rows=replace?r.rows:rows.concat(r.rows);}
async function open(id){fileHistory=false;const {grid,...query}=prefs.filters;const nav=await api('registers/vehicles?'+new URLSearchParams({query:JSON.stringify(query),grid:grid||'{}',seek:id}));registerMeta.navigation=nav.navigation;linkedTasks=null;taskError='';profile=await api('vehicles/'+id);files=rights('documents')?(await api('vehicles/'+id+'/files')).rows:[];request=null;mode='profile';tab='personal';review=null;preview=null;drafts={};draw();window.scrollTo(0,0);}
async function loadLinkedTasks(){const id=profile.id,requestId=profile.requestId||profile.request?.id;linkedTasks=null;taskError='';tab='tasks';draw();try{const r=await api('personnel/tasks?companyId='+encodeURIComponent(profile.companyId));if(profile?.id===id)linkedTasks=r.rows.filter(x=>x.payload?.vehicleId===id||x.source_id===id||x.source_type==='vehicle_registration'&&x.source_id===requestId);}catch{if(profile?.id===id)taskError=t('تعذر عرض المهام ضمن الصلاحيات الحالية.','Tasks could not be displayed with the current permissions.');}finally{if(profile?.id===id&&tab==='tasks')draw();}}
async function select(next){sync();if(!cap)await load();profile=null;request=null;mode=next;drafts={};draw();}
async function startRequest(customerId,name){sync();if(!cap)await load();clientContext={id:customerId,name};profile=null;request=null;mode='new-request';app.state.currentPage='vehicles';drafts={};draw();}
function requestForm(){return `<h2>${t('طلب مركبة من ملف العميل','Vehicle request from customer profile')}: ${e(clientContext?.name||clientContext?.id)}</h2><p>${t('هذه بيانات تقديرية؛ لا يطلب النظام اللوحة أو الموديل في الطلب الأولي.','Initial estimates only; no plate or model required at this stage.')}</p>`+form('request',[f('companyId',l('companyId'),'select','',companies('create'),true),f('vehicleType',l('vehicleType'),'text','',null,true),f('approximateValue',t('القيمة التقريبية','Approximate value'),'text','',null,true),f('expectedFunding',t('التمويل المتوقع','Expected funding'),'text','0',null,true),f('financeType',t('مصدر التمويل','Funding source'),'select','group',choices(['group','investor','cash','bank']),true),f('investorId',t('المستثمر النشط (لتمويل المستثمر فقط)','Active investor (investor funding only)'),'select','',references.investors),f('months',t('الأشهر عند الحاجة','Months if applicable'),'number',''),f('currency',l('currency'),'text','AED',null,true),f('notes',t('ملاحظات','Notes'),'textarea',''),f('exceptionReason',t('استثناء معتمد للعميل غير النشط، عند الحاجة','Authorized inactive-customer exception, if needed'),'textarea','')]);}
function registrations(){const r=request,p=rows.find(v=>v.requestId===r.id)||(r.vehicleId?{id:r.vehicleId,fileNumber:''}:null);return `<h2>${t('طلب','Request')} #${e(r.requestNumber)}</h2><p>${l(r.financeType)} — ${l(r.fundingState)} — ${e(co(r.companyId))}</p><p>${t('الموافقة ليست صرفاً؛ والتسجيل ليس إصدار فواتير.','Approval is not disbursement; registration is not invoicing.')}</p>`+(r.fundingState==='Requested'&&rights('funding_approve',r.companyId)?form('funding-decision',[f('approve',t('أوافق على التمويل المحدد','Approve specified funding'),'checkbox',true),f('reason',t('سبب القرار','Decision reason'),'textarea','',null,true)]):'')+(r.fundingState==='Approved'&&!r.funds?.length&&rights('disburse',r.companyId)?form('disburse',[f('receiverId',t('الموظف المستلم المخول','Authorized receiving employee'),'select','',references.employees,true),f('method',t('طريقة الصرف','Disbursement method'),'select','cash',choices(['cash','cheque','transfer']),true),f('source',t('مصدر الأموال','Source of funds'),'text','',null,true),f('date',t('التاريخ','Date'),'date',new Date().toISOString().slice(0,10),null,true),f('paymentOperationId',t('مرجع صرف بنكي معتمد للشيك/التحويل','Posted bank-payment ID for cheque/transfer')),f('evidence',t('توثيق الصرف','Disbursement evidence'),'textarea','',null,true)]):'')+table([t('العهدة','Custody'),t('الحالة','State'),t('تأكيد المستلم','Receiver confirmation')],(r.funds||[]).map(f=>[e(f.amount)+' '+e(f.currency),e(l(f.state)),f.state==='AwaitingReceipt'&&f.receiverId===actor?button('receive-funds',t('أؤكد الاستلام الفعلي','Confirm actual receipt'),f.id):'—']))+(p?button('open',t('فتح ملف المركبة','Open vehicle'),p.id):form('register',registrationFields({vehicleType:r.vehicleType,currency:r.currency}),t('حفظ ملف المركبة','Save vehicle file'),rights('create',r.companyId)));}
function registrationFields(d={}){return [f('vehicleType',l('vehicleType'),'text',d.vehicleType||'',null,true),...['make','model','year','color'].map(k=>f(k,l(k),'text',d[k]||'')),f('emirate',l('emirate'),'select',d.emirate||'',(ABCentral.emirates||[]).map(x=>({id:x.id,name:getLocale()==='ar'?x.name_ar:x.name_en}))),f('areaId',l('areaId'),'select',d.areaId||'',(ABCentral.areas||[]).filter(x=>(x.emirateId||x.emirate_id)===(d.emirate||'')).map(x=>({id:x.id,name:x.name||x.nameAr||x.name_ar||x.nameEn}))),...['plate','plateCode','vin'].map(k=>f(k,l(k),'text',d[k]||'')),f('registeredOn',l('registeredOn'),'date',d.registeredOn||''),f('ownershipExpiresOn',l('ownershipExpiresOn'),'date',d.ownershipExpiresOn||''),f('currency',l('currency'),'text',d.currency||'AED',null,true),f('notes',t('ملاحظات','Notes'),'textarea',d.notes||'')];}
function requestRows(){return `<p>${t('إنشاء طلب جديد من بروفايل العميل فقط. الطلبات أدناه لا تُعتبر مكتملة لمجرد الحفظ.','New requests originate only in a customer profile. Saved requests are not automatically completed.')}</p>`+table([t('الطلب','Request'),t('الشركة','Company'),t('التمويل','Funding'),t('الموافقة','Approval'),t('المركبة','Vehicle'),t('الإجراء','Action')],requests.filter(r=>mode!=='pending'||r.stage!=='completed').map(r=>{const v=rows.find(v=>v.requestId===r.id);return [e(r.requestNumber),e(co(r.companyId)),e(l(r.financeType)),e(l(r.fundingState))+' — '+e(l(r.stage)),v?button('open','#'+v.fileNumber,v.id):t('لم يسجل','Not registered'),button('request',t('متابعة الطلب','Continue request'),r.id)];}));}

function registerToolbar(){return `<div class="ve-actions"><button type="button" class="ghost-btn" data-rg-clear-all>${t('إزالة فلاتر الأعمدة','Clear column filters')}</button>${['excel','pdf','print','share'].map(format=>`<button type="button" class="ghost-btn" data-rg-export="${format}">${format==='print'?t('طباعة','Print'):format==='share'?t('مشاركة PDF','Share PDF'):format.toUpperCase()}</button>`).join('')}<label><input type="checkbox" data-rg-export-all>${t('جميع السجلات المسموحة (بدون الفلاتر)','All permitted records (ignore filters)')}</label></div>`;}
